/* ------------------------------------------------------------
   עמוד הפרטים · /info

   אל תבלבל בינו לבין `RIGHTS` — זה המכתב להוצאה, שנשלח פעם
   אחת. זה עמוד שיושב באתר ומקושר מכל מסך.

   למה עמוד אחד ולא ארבעה: הצהרת הנגישות חייבת קישור משלה
   ("מקום בולט", תקנה 35), וזה מה שיש לה. לשאר — פרטיות,
   גרסה, זכויות — אין דרישת מיקום כלל, ולכן הם יושבים יחד
   במקום שנקרא "פרטים". הודעת זכויות יוצרים אינה חובה חוקית
   בשום צורה: הזכות קמה עם היצירה, בלי רישום ובלי הודעה,
   וערכה ראייתי בלבד — שם על היצירה מקים חזקה שהוא היוצר.

   הסדר אינו מקרי. פרטיות היא מה שהורה בא לחפש, ולכן היא
   ראשונה; הזכויות אחרונות, ובתוכן מי שנתן לנו רשות קודם למי
   שבנה. שורת ה-© האחרונה נקראת כהשלמת רשימה, לא כהכרזה.

   בפסקת הדף האינטראקטיבי כל מילה נשקלה. "ביוזמה אישית"
   ו"בזמנו הפנוי" — הן שנוגעות לשאלה של מי היצירה. "פתוח
   לשימושם של לומדים ומסגרות שונות" — קובע שהתוכנית אינה
   בלעדית, ובא לפני האזכור שלה כדי שייקרא כנתינה ולא
   כהסתייגות. "הועמד לרשות" ולא "נמסר" — רישיון, לא העברת
   בעלות. "ללא תמורה וללא הגבלת זמן" — מה שהופך את זה למתנה
   שלמה ולא לתנאי.

   סעיף הפרטיות אומר גם את מה שפחות נוח: הצוות של כל מוסד
   רואה בלוח שמות מלאים וקצב לימוד, ושמות של זוכים ומצטיינים
   מתפרסמים. הצהרה שמזכירה רק את החלק הנעים גרועה מאין
   הצהרה. אם ישתנה שדה בטופס, או מה שהלוח מציג, או מה
   שמתפרסם — לתקן גם כאן וגם בהודעה שבטופס ההצטרפות.
   ------------------------------------------------------------ */
