/* ============================================================
   העדכון המתוזמן — מה שנשלח לר"ם במועד שהוא בחר.
   ============================================================
   הנוסח יושב כאן ולא בתוך השולח, כדי שיהיה ניתן לעריכה כמו
   כל מלל אחר בתוכנית.

   **המספרים הם שלו בלבד.** אין בעדכון השוואה לכיתה אחרת ולא
   ממוצע ישיבתי, וזו אינה השמטה: ר"ם של כיתה קטנה שרואה כיתה
   גדולה לצידו מקבל בעיקר את המסר שהוא נכשל, וזה בדיוק ההפך
   ממה שהעדכון בא לעשות.

   {cls} הכיתה · {n} כמה מתלמידיו באפליקציה · {done} כמה למדו
   את הדף · {daf} שם הדף · {parasha} הפרשה.
   ============================================================ */
/* ההזמנה לפינה האישית — ההתראה שמביאה את הצוות לשם.
   קצרה בכוונה: היא נקראת על מסך נעול, והשורה השנייה כבר
   נחתכת בחלק מהמכשירים. */
var PUSH_INVITE = {
  title: 'הפינה שלך בהדף השבועי',
  body:  'נפתחה לך פינה אישית: מתי לקבל עדכון על תלמידיך, ' +
         'ואיך לשלוח להם מילה. לחיצה כאן פותחת אותה.'
};

