/* מחיר לחוברת, לכל מהדורה בנפרד.
   price = המחיר בהזמנה מרוכזת · list = המחיר הרגיל ·
   min   = כמה עותקים צריך כדי שהמחיר המוזל בכלל יינתן.

   שתי ההוצאות התנו את ההנחה בכמות מינימלית, ולכן `min` מוצג בכל
   מקום שבו מופיע המחיר המוזל — אחרת מבטיחים לראשי החטיבות מחיר
   שעדיין לא מובטח. min:0 מבטל את ההערה.

   הערכים כאן הם ברירת מחדל; מסך הניהול ← מחירים דורס אותם. */
